def transform(grid):
    out=[r[:] for r in grid]
    h,w=len(grid),len(grid[0])
    bg=max(set(v for row in grid for v in row),key=lambda v:sum(r.count(v) for r in grid))
    for r in range(h-1):
        for c in range(w):
            v=grid[r][c]
            if v==bg: continue
            for dc in (-1,1):
                nc=c+dc
                if 0<=nc<w and grid[r+1][nc]==v:
                    rr,cc=r+2,nc+dc
                    while rr<h and 0<=cc<w:
                        if out[rr][cc]==bg: out[rr][cc]=v
                        rr+=1; cc+=dc
    return out
